<?php $labels = ['draft'=>'Draft','submitted'=>'Menunggu Approval Laboran','laboran_approved'=>'Menunggu Approval Kepala Lab','rejected'=>'Ditolak','approved'=>'Disetujui','completed'=>'Selesai']; $colors = ['draft'=>'secondary','submitted'=>'warning','laboran_approved'=>'info','rejected'=>'danger','approved'=>'success','completed'=>'primary']; ?>
<div class="page__section flex flex-col gap-4"><div class="card"><div class="card__header"><div><span class="card__title"><?= esc($proposal['event_name']) ?></span><div class="text-xs text-muted-foreground">Detail Proposal Peminjaman Asset</div></div><div class="card__action"><span class="badge badge--soft badge--<?= $colors[$proposal['status']] ?>"><?= $labels[$proposal['status']] ?></span><a class="button button--outline button--neutral button--sm" href="<?= base_url('peminjaman/asset-loans') ?>">Kembali</a></div></div><div class="card__body"><div class="grid grid-cols-1 md:grid-cols-2 gap-4"><div><span class="text-xs text-muted-foreground">Pemohon</span><strong><?= esc($proposal['full_name']) ?></strong><div><?= esc($proposal['identity_number']) ?> · <?= esc($proposal['email']) ?></div></div><div><span class="text-xs text-muted-foreground">Waktu Kegiatan</span><strong><?= esc(date('d M Y H:i', strtotime($proposal['event_start']))) ?> - <?= esc(date('d M Y H:i', strtotime($proposal['event_end']))) ?></strong></div></div></div></div><div class="card"><div class="card__header"><span class="card__title">Asset</span></div><div class="card__body"><div class="table-responsive"><table class="table"><thead><tr><th>Kode</th><th>Nama</th><th>Lokasi</th><th>Catatan</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= esc($item['asset_code']) ?></td><td><strong><?= esc($item['asset_name']) ?></strong><div class="text-xs text-muted-foreground"><?= esc($item['category'] ?: '-') ?></div></td><td><?= esc($item['laboratory_name'] ?: '-') ?> <?= esc($item['room_code'] ?: '') ?></td><td><?= esc($item['notes'] ?: '-') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php if ($approvalMode): ?><div class="card"><div class="card__body"><strong>Keputusan Approval</strong><form method="post" action="<?= base_url('peminjaman/asset-loans/' . $proposal['uuid'] . '/approve') ?>" style="display:inline;margin-left:1rem"><?= csrf_field() ?><button class="button button--success">Setujui</button></form><form method="post" action="<?= base_url('peminjaman/asset-loans/' . $proposal['uuid'] . '/reject') ?>" style="display:inline;margin-left:.5rem"><?= csrf_field() ?><input class="input" name="note" placeholder="Alasan penolakan"><button class="button button--danger">Tolak</button></form></div></div><?php endif; ?><div class="card"><div class="card__header"><span class="card__title">History Status</span></div><div class="card__body"><ul><?php foreach ($history as $entry): ?><li><?= esc($labels[$entry['from_status']] ?? 'Awal') ?> → <strong><?= esc($labels[$entry['to_status']] ?? $entry['to_status']) ?></strong> · <?= esc($entry['note'] ?: '-') ?></li><?php endforeach; ?></ul></div></div></div>
